-- COMM-10: uncapped, action-specific, reversible author engagement PRO Points.
alter table public.wf_profile_posts add column if not exists content_origin text not null default 'member'
  check(content_origin in ('member','sponsored','organization'));

create table public.wf_pro_engagement_awards(
 award_id uuid primary key default gen_random_uuid(),recipient_user_id text not null references public.users(user_id),actor_user_id text not null references public.users(user_id),
 source_post_id text not null references public.wf_profile_posts(profile_post_id) on delete cascade,content_kind text not null check(content_kind in('post','comment','poll','event')),
 content_id text not null,action_type text not null check(action_type in('like','comment','reply','share','poll_vote','rsvp')),
 points integer not null check(points in(1,2,3)),source_ref text not null,season date not null,occurred_at timestamptz not null,
 active boolean not null default true,awarded_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(recipient_user_id,actor_user_id,content_kind,content_id,action_type),check(recipient_user_id<>actor_user_id),check(season=date_trunc('quarter',season::timestamp)::date)
);
create index wf_pro_engagement_recipient_season_idx on public.wf_pro_engagement_awards(recipient_user_id,season) where active;
create index wf_pro_engagement_source_post_idx on public.wf_pro_engagement_awards(source_post_id,active);
create table public.wf_pro_engagement_season_corrections(
 id uuid primary key default gen_random_uuid(),season date not null references public.wf_pro_season_finalizations(season),award_id uuid not null references public.wf_pro_engagement_awards(award_id),
 recipient_user_id text not null references public.users(user_id),points_delta integer not null check(points_delta<>0),reason text not null,recorded_at timestamptz not null default now()
);
alter table public.wf_pro_engagement_awards enable row level security;alter table public.wf_pro_engagement_season_corrections enable row level security;
revoke all on public.wf_pro_engagement_awards,public.wf_pro_engagement_season_corrections from public,anon,authenticated;

create function security.pro_engagement_post_eligible(p_post_id text) returns boolean language sql stable security definer set search_path='' as $$
 select exists(
   select 1
   from public.wf_profile_posts p
   join public.users u on u.user_id=p.author_user_id and lower(u.status)='active'
   join public.wf_public_pages page on page.public_page_id=p.author_public_page_id
     and page.owner_user_id=p.author_user_id
     and page.entity_type in ('student','educator','staff','member')
   where p.profile_post_id=p_post_id and p.status='published' and p.content_origin='member'
     and (p.visibility='public' or (p.visibility='unlisted' and exists(
       select 1 from public.wf_community_post_audiences a
       join public.wf_community_groups g on g.group_id=a.group_id and g.visibility='public' and g.status='active'
       where a.profile_post_id=p.profile_post_id
     )))
 );
$$;
create function security.pro_engagement_points(p_action text) returns integer language sql immutable set search_path='' as $$select case p_action when 'like' then 1 when 'comment' then 2 when 'reply' then 2 when 'share' then 3 when 'poll_vote' then 1 when 'rsvp' then 3 end$$;

create function security.pro_engagement_sync(p_recipient text,p_actor text,p_post text,p_kind text,p_content text,p_action text,p_source text,p_active boolean,p_occurred timestamptz) returns void language plpgsql volatile security definer set search_path='' as $$
declare pts int:=security.pro_engagement_points(p_action);existing public.wf_pro_engagement_awards;desired boolean:=coalesce(p_active,false) and security.pro_engagement_post_eligible(p_post) and p_recipient<>p_actor;aid uuid;delta int;
begin if pts is null or p_recipient is null or p_actor is null then return;end if;perform pg_advisory_xact_lock(hashtextextended(concat_ws(':','pro-engagement',p_recipient,p_actor,p_kind,p_content,p_action),0));
 select * into existing from public.wf_pro_engagement_awards where recipient_user_id=p_recipient and actor_user_id=p_actor and content_kind=p_kind and content_id=p_content and action_type=p_action for update;
 if not found then if not desired then return;end if;insert into public.wf_pro_engagement_awards(recipient_user_id,actor_user_id,source_post_id,content_kind,content_id,action_type,points,source_ref,season,occurred_at) values(p_recipient,p_actor,p_post,p_kind,p_content,p_action,pts,p_source,date_trunc('quarter',p_occurred at time zone 'America/Chicago')::date,p_occurred) returning award_id into aid;delta:=pts;
 elsif existing.active=desired then return;
 else update public.wf_pro_engagement_awards set active=desired,updated_at=now(),source_ref=p_source where award_id=existing.award_id returning award_id into aid;delta:=case when desired then pts else -pts end;end if;
 insert into public.platform_audit_events(actor_auth_user_id,actor_user_id,action,entity_type,entity_id,source,metadata) values(auth.uid(),p_actor,case when desired then 'PRO_ENGAGEMENT_AWARDED' else 'PRO_ENGAGEMENT_REVERSED' end,'pro_engagement_award',aid::text,'workforce-domain-event',jsonb_build_object('recipientUserId',p_recipient,'sourcePostId',p_post,'contentKind',p_kind,'contentId',p_content,'actionType',p_action,'pointsDelta',delta));
 if exists(select 1 from public.wf_pro_season_finalizations where season=coalesce(existing.season,date_trunc('quarter',p_occurred at time zone 'America/Chicago')::date)) then insert into public.wf_pro_engagement_season_corrections(season,award_id,recipient_user_id,points_delta,reason) values(coalesce(existing.season,date_trunc('quarter',p_occurred at time zone 'America/Chicago')::date),aid,p_recipient,delta,'Engagement source changed after season finalization');end if;
end $$;

create function security.pro_engagement_reconcile_post(p_post text) returns void language plpgsql volatile security definer set search_path='' as $$
declare r record;recipient text;
begin
 if not security.pro_engagement_post_eligible(p_post) then for r in select * from public.wf_pro_engagement_awards where source_post_id=p_post and active loop perform security.pro_engagement_sync(r.recipient_user_id,r.actor_user_id,r.source_post_id,r.content_kind,r.content_id,r.action_type,r.source_ref,false,r.occurred_at);end loop;return;end if;
 select author_user_id into recipient from public.wf_profile_posts where profile_post_id=p_post;
 for r in select actor_user_id,profile_post_reaction_id source_ref,created_at from public.wf_profile_post_reactions where profile_post_id=p_post and reaction_type='like' loop perform security.pro_engagement_sync(recipient,r.actor_user_id,p_post,'post',p_post,'like',r.source_ref,true,r.created_at);end loop;
 for r in select actor_user_id,min(profile_post_share_id) source_ref,min(created_at) created_at from public.wf_profile_post_shares where profile_post_id=p_post group by actor_user_id loop perform security.pro_engagement_sync(recipient,r.actor_user_id,p_post,'post',p_post,'share',r.source_ref,true,r.created_at);end loop;
 for r in select c.author_user_id actor_user_id,c.profile_post_id,c.parent_comment_id,c.profile_post_comment_id,c.created_at,coalesce(parent.author_user_id,recipient) recipient from public.wf_profile_post_comments c left join public.wf_profile_post_comments parent on parent.profile_post_comment_id=c.parent_comment_id where c.profile_post_id=p_post and c.status='published' and (c.parent_comment_id is null or parent.status='published') loop perform security.pro_engagement_sync(r.recipient,r.actor_user_id,p_post,case when r.parent_comment_id is null then 'post' else 'comment' end,coalesce(r.parent_comment_id,p_post),case when r.parent_comment_id is null then 'comment' else 'reply' end,r.profile_post_comment_id,true,r.created_at);end loop;
 for r in select b.voter_user_id actor_user_id,b.ballot_id source_ref,b.created_at from public.wf_post_poll_ballots b join public.wf_post_polls poll on poll.profile_post_id=b.profile_post_id and poll.status<>'cancelled' where b.profile_post_id=p_post loop perform security.pro_engagement_sync(recipient,r.actor_user_id,p_post,'poll',p_post,'poll_vote',r.source_ref,true,r.created_at);end loop;
 for r in select e.user_id actor_user_id,e.status,e.first_qualified_at,e.updated_at from public.wf_post_event_rsvps e join public.wf_post_events v on v.profile_post_id=e.profile_post_id and v.status='published' where e.profile_post_id=p_post and e.status in('interested','going') loop perform security.pro_engagement_sync(recipient,r.actor_user_id,p_post,'event',p_post,'rsvp',p_post||':'||r.actor_user_id,true,coalesce(r.first_qualified_at,r.updated_at));end loop;
 for r in select a.* from public.wf_pro_engagement_awards a where a.source_post_id=p_post and a.active and not(case a.action_type when 'like' then exists(select 1 from public.wf_profile_post_reactions x where x.profile_post_id=p_post and x.actor_user_id=a.actor_user_id and x.reaction_type='like') when 'share' then exists(select 1 from public.wf_profile_post_shares x where x.profile_post_id=p_post and x.actor_user_id=a.actor_user_id) when 'comment' then exists(select 1 from public.wf_profile_post_comments x where x.profile_post_id=p_post and x.author_user_id=a.actor_user_id and x.parent_comment_id is null and x.status='published') when 'reply' then exists(select 1 from public.wf_profile_post_comments x join public.wf_profile_post_comments parent on parent.profile_post_comment_id=x.parent_comment_id and parent.status='published' where x.profile_post_id=p_post and x.author_user_id=a.actor_user_id and x.parent_comment_id=a.content_id and x.status='published') when 'poll_vote' then exists(select 1 from public.wf_post_poll_ballots x join public.wf_post_polls poll on poll.profile_post_id=x.profile_post_id and poll.status<>'cancelled' where x.profile_post_id=p_post and x.voter_user_id=a.actor_user_id) when 'rsvp' then exists(select 1 from public.wf_post_event_rsvps x join public.wf_post_events v on v.profile_post_id=x.profile_post_id and v.status='published' where x.profile_post_id=p_post and x.user_id=a.actor_user_id and x.status in('interested','going')) else false end) loop perform security.pro_engagement_sync(r.recipient_user_id,r.actor_user_id,r.source_post_id,r.content_kind,r.content_id,r.action_type,r.source_ref,false,r.occurred_at);end loop;
end $$;

create function security.pro_engagement_source_trigger() returns trigger language plpgsql volatile security definer set search_path='' as $$
declare post_id text;begin post_id:=case tg_table_name when 'wf_profile_post_reactions' then coalesce(new.profile_post_id,old.profile_post_id) when 'wf_profile_post_shares' then coalesce(new.profile_post_id,old.profile_post_id) when 'wf_profile_post_comments' then coalesce(new.profile_post_id,old.profile_post_id) when 'wf_post_poll_ballots' then coalesce(new.profile_post_id,old.profile_post_id) when 'wf_post_polls' then coalesce(new.profile_post_id,old.profile_post_id) when 'wf_post_event_rsvps' then coalesce(new.profile_post_id,old.profile_post_id) when 'wf_post_events' then coalesce(new.profile_post_id,old.profile_post_id) when 'wf_profile_posts' then coalesce(new.profile_post_id,old.profile_post_id) when 'wf_community_post_audiences' then coalesce(new.profile_post_id,old.profile_post_id) end;perform security.pro_engagement_reconcile_post(post_id);if tg_op='DELETE' then return old;end if;return new;end $$;
create function security.pro_engagement_group_trigger() returns trigger language plpgsql volatile security definer set search_path='' as $$
declare r record;begin for r in select profile_post_id from public.wf_community_post_audiences where group_id=new.group_id loop perform security.pro_engagement_reconcile_post(r.profile_post_id);end loop;return new;end $$;
create trigger pro_engagement_like after insert or delete on public.wf_profile_post_reactions for each row execute function security.pro_engagement_source_trigger();
create trigger pro_engagement_share after insert or delete on public.wf_profile_post_shares for each row execute function security.pro_engagement_source_trigger();
create trigger pro_engagement_comment after insert or delete or update of status on public.wf_profile_post_comments for each row execute function security.pro_engagement_source_trigger();
create trigger pro_engagement_poll after insert or delete on public.wf_post_poll_ballots for each row execute function security.pro_engagement_source_trigger();
create trigger pro_engagement_poll_state after update of status on public.wf_post_polls for each row execute function security.pro_engagement_source_trigger();
create trigger pro_engagement_rsvp after insert or update of status or delete on public.wf_post_event_rsvps for each row execute function security.pro_engagement_source_trigger();
create trigger pro_engagement_event_state after update of status on public.wf_post_events for each row execute function security.pro_engagement_source_trigger();
create trigger pro_engagement_post_state after update of status,visibility,content_origin on public.wf_profile_posts for each row execute function security.pro_engagement_source_trigger();
create trigger pro_engagement_audience after insert or delete on public.wf_community_post_audiences for each row execute function security.pro_engagement_source_trigger();
create trigger pro_engagement_group_state after update of status,visibility on public.wf_community_groups for each row execute function security.pro_engagement_group_trigger();

create or replace function security.pro_finalize_season(p_season date,p_actor text default null) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v_version integer;v_count integer;v_end date;v_existing timestamptz;
begin if p_season is null or p_season<>date_trunc('quarter',p_season::timestamp)::date or p_season>=date_trunc('quarter',now() at time zone 'America/Chicago')::date then raise exception 'Only ended calendar-quarter seasons can be finalized' using errcode='22023';end if;if p_actor is not null and not exists(select 1 from public.users where user_id=p_actor and lower(status)='active') then raise exception 'Finalization actor unavailable' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('pro-season:'||p_season::text,0));select finalized_at into v_existing from public.wf_pro_season_finalizations where season=p_season;if found then return jsonb_build_object('season',p_season,'finalizedAt',v_existing,'duplicate',true);end if;v_version:=security.pro_level_version_for(p_season);if v_version is null then raise exception 'Level configuration unavailable for season';end if;v_end:=(p_season+interval '3 months - 1 day')::date;select count(*) into v_count from public.wf_student_profiles p join public.users u on u.user_id=p.user_id where lower(u.status)='active';
 insert into public.wf_pro_season_finalizations(season,season_ends,level_version,scoring_snapshot,student_count,finalized_by) values(p_season,v_end,v_version,jsonb_build_object('timezone','America/Chicago','competitionRanking','1,1,3','rules',coalesce((select jsonb_agg(to_jsonb(r) order by r.code) from public.wf_pro_rules r),'[]'::jsonb),'engagement',jsonb_build_object('like',1,'comment',2,'reply',2,'share',3,'poll_vote',1,'rsvp',3,'uncapped',true)),v_count,p_actor);
 with scores as(select p.student_id,p.school_id institution_id,p.cohort_id,coalesce((select sum(l.points) from public.wf_pro_ledger l where l.student_id=p.student_id and l.season=p_season),0)+coalesce((select sum(e.points) from public.wf_pro_engagement_awards e where e.recipient_user_id=p.user_id and e.season=p_season and e.active),0) season_points,coalesce((select sum(l.points) from public.wf_pro_ledger l where l.student_id=p.student_id and l.season<=p_season),0)+coalesce((select sum(e.points) from public.wf_pro_engagement_awards e where e.recipient_user_id=p.user_id and e.season<=p_season and e.active),0) lifetime_points from public.wf_student_profiles p join public.users u on u.user_id=p.user_id and lower(u.status)='active'),ranked as(select s.*,case when s.cohort_id is null then null else rank() over(partition by s.cohort_id order by s.season_points desc)end cohort_rank,case when s.institution_id is null then null else rank() over(partition by s.institution_id order by s.season_points desc)end institution_rank,rank() over(order by s.season_points desc)txkpro_rank from scores s)
 insert into public.wf_pro_season_standings(season,student_id,institution_id,cohort_id,season_points,lifetime_points,lifetime_level,cohort_rank,institution_rank,txkpro_rank) select p_season,r.student_id,r.institution_id,r.cohort_id,r.season_points,r.lifetime_points,(select count(*)::integer from public.wf_pro_level_thresholds t where t.version=v_version and t.minimum_points<=r.lifetime_points),r.cohort_rank,r.institution_rank,r.txkpro_rank from ranked r;
 insert into public.platform_audit_events(actor_auth_user_id,actor_user_id,action,entity_type,entity_id,source,metadata) values(auth.uid(),p_actor,'PRO_SEASON_FINALIZED','pro_points_season',p_season::text,'workforce-domain-event',jsonb_build_object('studentCount',v_count,'levelVersion',v_version,'scoringSnapshot',true,'engagementIncluded',true));return jsonb_build_object('season',p_season,'seasonEnds',v_end,'studentCount',v_count,'levelVersion',v_version,'duplicate',false);end $$;

alter function security.pro_summary(text,boolean) rename to pro_summary_before_engagement;
create function security.pro_summary(s text,public_view boolean default false) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare base jsonb;u text;q date;season_points bigint;lifetime_points bigint;eng_season bigint;eng_life bigint;v_version int;lvl int;lvl_min bigint;next_lvl int;next_min bigint;ranks jsonb;
begin base:=security.pro_summary_before_engagement(s,public_view);if base->'progress' is null or base->'progress'='null'::jsonb then return base;end if;select user_id into u from public.wf_student_profiles where student_id=s;q:=date_trunc('quarter',now() at time zone 'America/Chicago')::date;select coalesce(sum(points) filter(where season=q and active),0),coalesce(sum(points) filter(where active),0) into eng_season,eng_life from public.wf_pro_engagement_awards where recipient_user_id=u;season_points:=(base#>>'{progress,points}')::bigint+eng_season;lifetime_points:=(base#>>'{progress,lifetime}')::bigint+eng_life;v_version:=security.pro_level_version_for(q);select level,minimum_points into lvl,lvl_min from public.wf_pro_level_thresholds where version=v_version and minimum_points<=lifetime_points order by minimum_points desc limit 1;select level,minimum_points into next_lvl,next_min from public.wf_pro_level_thresholds where version=v_version and minimum_points>lifetime_points order by minimum_points limit 1;
 with scores as(select p.student_id,p.school_id,p.cohort_id,coalesce((select sum(l.points) from public.wf_pro_ledger l where l.student_id=p.student_id and l.season=q),0)+coalesce((select sum(e.points) from public.wf_pro_engagement_awards e where e.recipient_user_id=p.user_id and e.season=q and e.active),0) pts from public.wf_student_profiles p join public.users x on x.user_id=p.user_id and lower(x.status)='active'),target as(select * from scores where student_id=s) select jsonb_build_object('cohort',case when t.cohort_id is null then null else(select count(*)+1 from scores x where x.cohort_id=t.cohort_id and x.pts>t.pts)end,'institution',case when t.school_id is null then null else(select count(*)+1 from scores x where x.school_id=t.school_id and x.pts>t.pts)end,'txkpro',(select count(*)+1 from scores x where x.pts>t.pts)) into ranks from target t;
 base:=jsonb_set(base,'{progress,points}',to_jsonb(season_points));base:=jsonb_set(base,'{progress,lifetime}',to_jsonb(lifetime_points));base:=jsonb_set(base,'{progress,level}',to_jsonb(coalesce(lvl,1)));base:=jsonb_set(base,'{progress,levelMinimum}',to_jsonb(coalesce(lvl_min,0)));base:=jsonb_set(base,'{progress,nextLevel}',coalesce(to_jsonb(next_lvl),'null'::jsonb));base:=jsonb_set(base,'{progress,nextLevelPoints}',coalesce(to_jsonb(next_min),'null'::jsonb));base:=jsonb_set(base,'{progress,rankings}',coalesce(ranks,'{}'::jsonb));return base;end $$;

create function public.pro_engagement_self() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare u text:=security.pro_actor();s text;q date:=date_trunc('quarter',now() at time zone 'America/Chicago')::date;eng_season bigint;eng_life bigint;base_season bigint:=0;base_life bigint:=0;season_points bigint;lifetime_points bigint;v_version int;lvl int;
begin
 select student_id into s from public.wf_student_profiles where user_id=u;
 select coalesce(sum(points) filter(where season=q and active),0),coalesce(sum(points) filter(where active),0) into eng_season,eng_life from public.wf_pro_engagement_awards where recipient_user_id=u;
 if s is not null then select coalesce(sum(points) filter(where season=q),0),coalesce(sum(points),0) into base_season,base_life from public.wf_pro_ledger where student_id=s;end if;
 season_points:=base_season+eng_season;lifetime_points:=base_life+eng_life;v_version:=security.pro_level_version_for(q);
 select level into lvl from public.wf_pro_level_thresholds where version=v_version and minimum_points<=lifetime_points order by minimum_points desc limit 1;
 return jsonb_build_object('season',q,'seasonPoints',season_points,'lifetimePoints',lifetime_points,'seasonalEngagementPoints',eng_season,'lifetimeEngagementPoints',eng_life,'lifetimeLevel',coalesce(lvl,1),'rankEligible',s is not null);
end $$;

revoke all on function security.pro_engagement_post_eligible(text),security.pro_engagement_points(text),security.pro_engagement_sync(text,text,text,text,text,text,text,boolean,timestamptz),security.pro_engagement_reconcile_post(text),security.pro_engagement_source_trigger(),security.pro_engagement_group_trigger(),security.pro_summary_before_engagement(text,boolean),security.pro_summary(text,boolean),public.pro_engagement_self() from public,anon,authenticated,service_role;
grant execute on function security.pro_summary(text,boolean) to authenticated;grant execute on function public.pro_engagement_self() to authenticated;
